/* @lc app=leetcode id=1761 lang=kotlin */ class Solution { fun minTrioDegree(n: Int, edges: Array<IntArray>): Int = Array(n + 1) { BooleanArray(n + 1) }.also { a -> edges.forEach { (u, v) -> a[u][v] = true.also { a[v][u] = true } } }.let { a -> IntArray(n + 1) { i -> a[i].count { it } }.let { d -> (1..n).flatMap { i -> (i + 1..n).filter { a[i][it] }.flatMap { j -> (j + 1..n).filter { a[i][it] && a[j][it] }.map { k -> d[i] + d[j] + d[k] - 6 } } }.minOrNull() ?: -1 } } }